def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]

    # The compact colored figure is the stamp; isolated target markers are
    # the other color occurring as single cells.
    from collections import Counter
    counts = Counter(grid[r][c] for r, c in cells)
    target_color = None
    for color, n in counts.items():
        if n == 2:
            target_color = color
            break
    if target_color is None:
        return [row[:] for row in grid]

    targets = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == target_color]

    # Find the small connected non-background object not consisting of targets.
    remaining = {(r, c) for r, c in cells if grid[r][c] != target_color}
    comps = []
    while remaining:
        seed = remaining.pop()
        comp = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in remaining:
                    remaining.remove(p)
                    comp.add(p)
                    stack.append(p)
        comps.append(comp)
    if not comps:
        return [row[:] for row in grid]
    comp = max(comps, key=len)
    minr, maxr = min(r for r,c in comp), max(r for r,c in comp)
    minc, maxc = min(c for r,c in comp), max(c for r,c in comp)
    cr, cc = (minr + maxr)//2, (minc + maxc)//2

    stamp = [(r-cr, c-cc, grid[r][c]) for r,c in comp]
    out = [row[:] for row in grid]
    for r, c in targets:
        for dr, dc, color in stamp:
            rr, cc2 = r+dr, c+dc
            if 0 <= rr < h and 0 <= cc2 < w:
                out[rr][cc2] = color
    return out
